import { randomUUID } from 'node:crypto';
import { User } from './User.js';
import { UserStore } from './UserStore.js';

/**
 * Validates display names and issues one user id per name.
 * @trace DSN-021 REQ-008
 */
export class UserService {
  constructor(private readonly userStore: UserStore) {}

  /** Validates the display name, rejects a taken name, and stores a new user with a fresh id. Throws if the name is 2 to 20 characters missing or already taken. */
  async register(displayName: string): Promise<User> {
    if (displayName.length < 2 || displayName.length > 20) {
      throw new Error('Display name must be 2 to 20 characters');
    }
    const existing = await this.userStore.findByName(displayName);
    if (existing !== null) {
      throw new Error(`Display name ${displayName} is already taken`);
    }
    return this.userStore.save(new User(randomUUID(), displayName));
  }
}

import { ItemService } from './ItemService.js';
import { Item } from './Item.js';
import { ItemView } from './ItemView.js';
import { Currency } from './Currency.js';

/**
 * HTTP-facing item operations: listing, viewing and browsing open auctions.
 *
 * @trace DSN-019 REQ-001 REQ-005 REQ-004
 */
export class ItemController {
  constructor(private readonly itemService: ItemService) {}

  /** Lists a new item for a seller; throws Error when a field is missing or invalid. */
  async listItem(userId: string, title: string, startingPrice: number, endTime: string, currency: string): Promise<Item> {
    if (!userId) throw new Error('Seller id is required');
    if (!title) throw new Error('Title is required');
    if (typeof startingPrice !== 'number' || !Number.isFinite(startingPrice) || startingPrice < 0) {
      throw new Error('Starting price must be a non-negative number');
    }
    if (!endTime) throw new Error('End time is required');
    const end = new Date(endTime);
    if (Number.isNaN(end.getTime())) throw new Error('End time is not a valid date');
    if (!currency) throw new Error('Currency is required');
    if (!Object.values(Currency).includes(currency as Currency)) {
      throw new Error(`Currency ${currency} is not supported`);
    }
    return this.itemService.listItem(userId, title, startingPrice, end, currency);
  }

  /** Returns an item with its display currency; throws Error when the display currency is not CHF, EUR or USD, or Item not found. */
  async getItem(id: string, displayCurrency: string | undefined): Promise<ItemView> {
    let display: Currency | null = null;
    if (displayCurrency !== undefined && displayCurrency !== '') {
      if (!Object.values(Currency).includes(displayCurrency as Currency)) {
        throw new Error(`Display currency ${displayCurrency} is not supported`);
      }
      display = displayCurrency as Currency;
    }
    const item = await this.itemService.getItem(id);
    return {
      item,
      displayCurrency: display,
      convertedStartingPrice: null,
      convertedHighestBid: null,
    };
  }

  /** Returns all items whose auctions are currently open. */
  async listOpenItems(): Promise<Item[]> {
    return this.itemService.listOpenItems();
  }
}

import { ItemService } from './ItemService.js';

/**
 * Periodic job that closes auctions whose end time was reached.
 *
 * @trace DSN-024 REQ-004
 */
export class AuctionCloser {
  constructor(private readonly itemService: ItemService, public intervalMs: number) {}

  /** Closes every auction due at the current time; propagates errors from ItemService. */
  async tick(): Promise<void> {
    await this.itemService.closeDueAuctions(new Date());
  }
}

import { randomUUID } from 'node:crypto';
import { Item } from './Item.js';
import { ItemStore } from './ItemStore.js';
import { UserStore } from './UserStore.js';
import { AuctionEventPublisher } from './AuctionEventPublisher.js';
import { Currency } from './Currency.js';
import { AuctionStatus } from './AuctionStatus.js';

const ALLOWED_CURRENCIES: string[] = [Currency.CHF, Currency.EUR, Currency.USD];

/**
 * Creates and reads items and closes auctions whose end time has been reached.
 * @trace DSN-022 REQ-001 REQ-004
 */
export class ItemService {
  constructor(private readonly itemStore: ItemStore, private readonly userStore: UserStore, private readonly auctionEventPublisher: AuctionEventPublisher) {}

  /** Creates an open auction item; throws an Error if a field is missing or invalid. */
  async listItem(sellerId: string, title: string, startingPrice: number, endTime: Date, currency: string): Promise<Item> {
    if (!sellerId) {
      throw new Error('Seller id is required');
    }
    if (!title) {
      throw new Error('Title is required');
    }
    if (typeof startingPrice !== 'number' || !Number.isFinite(startingPrice) || startingPrice < 0) {
      throw new Error('Starting price is required and must be a non-negative number');
    }
    if (!(endTime instanceof Date) || Number.isNaN(endTime.getTime())) {
      throw new Error('End time is required');
    }
    if (!currency) {
      throw new Error('Currency is required');
    }
    if (!ALLOWED_CURRENCIES.includes(currency)) {
      throw new Error(`Currency ${currency} is not supported`);
    }
    const item = new Item(
      randomUUID(),
      sellerId,
      title,
      startingPrice,
      currency as Currency,
      endTime,
      AuctionStatus.open,
      null,
      null,
      null,
    );
    return this.itemStore.saveItem(item);
  }

  /** Returns the item with the given id; throws an Error ending in not found when it does not exist. */
  async getItem(id: string): Promise<Item> {
    const item = await this.itemStore.findItem(id);
    if (!item) {
      throw new Error(`Item ${id} not found`);
    }
    return item;
  }

  /** Returns all items that are currently open for bids. */
  async listOpenItems(): Promise<Item[]> {
    return this.itemStore.findOpenItems();
  }

  /** Closes every open item whose end time has been reached, recording the winner or marking it unsold, and publishes each closure. */
  async closeDueAuctions(now: Date): Promise<void> {
    const due = await this.itemStore.findDueItems(now);
    for (const item of due) {
      if (item.highestBidderId) {
        item.status = AuctionStatus.closed;
        item.winnerId = item.highestBidderId;
      } else {
        item.status = AuctionStatus.unsold;
        item.winnerId = null;
      }
      const saved = await this.itemStore.saveItem(item);
      await this.auctionEventPublisher.publishAuctionClosed(saved);
    }
  }
}

import { Currency } from '../auction-api/Currency.js';
import { FrankfurterClient } from './FrankfurterClient.js';

interface CachedRates {
  rates: Record<string, number>;
  fetchedAt: number;
}

/**
 * Converts prices for display using rates cached for a configurable time; returns null when unavailable.
 * @trace DSN-025 REQ-005 REQ-010
 */
export class ExchangeRateService {
  private readonly cache = new Map<Currency, CachedRates>();

  constructor(private readonly frankfurterClient: FrankfurterClient, public cacheTtlMs: number) {}

  /** Converts an item-currency amount to the display currency; returns null when no rate is available, throws on invalid input. */
  async convert(amount: number, from: Currency, to: Currency): Promise<number | null> {
    if (!Number.isFinite(amount) || amount < 0) {
      throw new Error(`Invalid amount ${amount}`);
    }
    if (!Object.values(Currency).includes(from)) {
      throw new Error(`Unsupported currency ${from}`);
    }
    if (!Object.values(Currency).includes(to)) {
      throw new Error(`Unsupported currency ${to}`);
    }
    if (from === to) {
      return amount;
    }
    const rates = await this.getRates(from);
    if (rates === null) {
      return null;
    }
    const rate = rates[to];
    if (typeof rate !== 'number') {
      return null;
    }
    return amount * rate;
  }

  private async getRates(base: Currency): Promise<Record<string, number> | null> {
    const cached = this.cache.get(base);
    if (cached && Date.now() - cached.fetchedAt < this.cacheTtlMs) {
      return cached.rates;
    }
    try {
      const rates = await this.frankfurterClient.fetchRates(base);
      this.cache.set(base, { rates, fetchedAt: Date.now() });
      return rates;
    } catch {
      return null;
    }
  }
}

import { randomUUID } from 'node:crypto';
import { Bid } from './Bid.js';
import { Item } from './Item.js';
import { User } from './User.js';
import { ItemStore } from './ItemStore.js';
import { BidEventPublisher } from './BidEventPublisher.js';
import { UserStore } from './UserStore.js';

const LATE_BID_WINDOW_MS = 2 * 60 * 1000;
const EXTENSION_MS = 2 * 60 * 1000;
const MIN_INCREMENT = 1;

/**
 * Validates and stores bids, extends end time, publishes events to the event feed.
 * @trace DSN-023 REQ-002 REQ-009 REQ-003 REQ-011
 */
export class BidService {
  /** Creates the service with its item store, event publisher and user store. */
  constructor(
    private readonly itemStore: ItemStore,
    private readonly bidEventPublisher: BidEventPublisher,
    private readonly userStore: UserStore,
  ) {}

  /** Validates and stores a bid, extends a late auction and publishes it; throws if the item or bidder is not found or the bid is invalid. */
  async placeBid(itemId: string, bidderId: string, amount: number): Promise<Bid> {
    if (!Number.isFinite(amount) || amount <= 0) {
      throw new Error('Bid amount must be a positive number');
    }
    const item: Item | null = await this.itemStore.findItem(itemId);
    if (item === null) {
      throw new Error(`Item ${itemId} not found`);
    }
    const bidder: User | null = await this.userStore.findByName(bidderId);
    if (bidder === null) {
      throw new Error(`Bidder ${bidderId} not found`);
    }
    const now = Date.now();
    const endTime = item.endTime.getTime();
    if (endTime <= now) {
      throw new Error(`Item ${itemId} auction has ended`);
    }
    if (item.sellerId === bidderId) {
      throw new Error('Seller cannot bid on their own item');
    }
    const highest = item.highestBid;
    if (highest === null) {
      if (amount < item.startingPrice) {
        throw new Error(`First bid must be at least the starting price ${item.startingPrice}`);
      }
    } else if (amount < highest + MIN_INCREMENT) {
      throw new Error(`Bid must be at least ${MIN_INCREMENT} higher than ${highest}`);
    }

    const bid = new Bid(randomUUID(), itemId, bidderId, amount, new Date(now));
    await this.itemStore.saveBid(bid);
    item.highestBid = amount;
    if (endTime - now <= LATE_BID_WINDOW_MS) {
      item.endTime = new Date(endTime + EXTENSION_MS);
    }
    const saved = await this.itemStore.saveItem(item);
    await this.bidEventPublisher.publishBidAccepted(bid, saved);
    return bid;
  }
}

import { Currency } from '../auction-api/Currency.js';

const FRANKFURTER_URL = 'https://api.frankfurter.app';
const CACHE_TTL_MS = 60 * 60 * 1000;

interface CachedRates {
  fetchedAt: number;
  rates: Record<string, number>;
}

/**
 * Fetches display-currency exchange rates from the Frankfurter API and caches them for one hour.
 * @trace DSN-026 REQ-005 REQ-010
 */
export class FrankfurterClient {
  private readonly cache: Map<Currency, CachedRates> = new Map();

  constructor() {}

  /** Returns rates for the base currency, from cache when younger than one hour; throws an Error when Frankfurter cannot be reached or answers with an error. */
  async fetchRates(base: Currency): Promise<Record<string, number>> {
    const cached = this.cache.get(base);
    if (cached && Date.now() - cached.fetchedAt < CACHE_TTL_MS) {
      return { ...cached.rates };
    }
    const response = await fetch(`${FRANKFURTER_URL}/latest?from=${encodeURIComponent(base)}`, {
      headers: { Accept: 'application/json' },
      signal: AbortSignal.timeout(5000),
    });
    if (!response.ok) {
      throw new Error(`Frankfurter responded with status ${response.status}`);
    }
    const body = (await response.json()) as { rates?: Record<string, number> };
    if (!body.rates || typeof body.rates !== 'object') {
      throw new Error('Frankfurter response contained no rates');
    }
    const rates: Record<string, number> = { ...body.rates };
    this.cache.set(base, { fetchedAt: Date.now(), rates });
    return { ...rates };
  }
}

import { EventFeed } from './EventFeed.js';
import { Bid } from './Bid.js';
import { Item } from './Item.js';

/**
 * Publishes accepted bid events to the internal ws event feed.
 *
 * @trace DSN-031 REQ-003 REQ-007 REQ-011
 */
export class BidEventPublisher {
  constructor(private readonly eventFeed: EventFeed) {}

  /** Publishes an accepted bid on the item's topic; throws if the bid or item is missing. */
  async publishBidAccepted(bid: Bid, item: Item): Promise<void> {
    if (!bid) {
      throw new Error('Bid is required');
    }
    if (!item) {
      throw new Error('Item is required');
    }
    const payload = JSON.stringify({
      itemId: item.id,
      bidId: bid.id,
      bidderId: bid.bidderId,
      amount: bid.amount,
      placedAt: bid.placedAt.toISOString(),
      highestBidAmount: item.highestBidAmount,
      highestBidderId: item.highestBidderId,
    });
    this.eventFeed.publish(`item:${item.id}`, payload);
  }
}

import { EventFeed } from './EventFeed.js';
import { Item } from './Item.js';

/**
 * Publishes auction closed events to the internal ws event feed.
 *
 * @trace DSN-030 REQ-003 REQ-004 REQ-007
 */
export class AuctionEventPublisher {
  constructor(private readonly eventFeed: EventFeed) {}

  /** Publishes the closed state, winner and final bid of an item to the event feed; throws if the item has no id. */
  async publishAuctionClosed(item: Item): Promise<void> {
    if (!item.id) {
      throw new Error('Item id is required to publish an auction closed event');
    }
    const payload = JSON.stringify({
      itemId: item.id,
      status: item.status,
      winnerId: item.winnerId,
      highestBidAmount: item.highestBidAmount,
      highestBidderId: item.highestBidderId,
    });
    this.eventFeed.publish(`auction.closed.${item.id}`, payload);
  }
}

import { DatabaseSync } from 'node:sqlite';
import { User } from './User.js';

/**
 * Persists users with a unique display name in the API server's SQLite database.
 * @trace DSN-028 REQ-008
 */
export class UserStore {
  private readonly db: DatabaseSync;

  constructor(db: DatabaseSync) {
    this.db = db;
    this.db.exec(
      'CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, display_name TEXT NOT NULL UNIQUE)'
    );
  }

  /** Returns the user with the given display name, or null when none has it. */
  async findByName(displayName: string): Promise<User | null> {
    const row = this.db
      .prepare('SELECT id, display_name AS displayName FROM users WHERE display_name = ?')
      .get(displayName) as unknown as { id: string; displayName: string } | undefined;
    return row ? new User(row.id, row.displayName) : null;
  }

  /** Inserts a new user or updates the stored one; throws if the name is invalid or taken by another user. */
  async save(user: User): Promise<User> {
    const length = user.displayName.length;
    if (length < 2 || length > 20) {
      throw new Error('Display name must be 2 to 20 characters');
    }
    const taken = this.db
      .prepare('SELECT id FROM users WHERE display_name = ? AND id <> ?')
      .get(user.displayName, user.id) as unknown as { id: string } | undefined;
    if (taken) {
      throw new Error(`Display name ${user.displayName} already taken`);
    }
    const existing = this.db
      .prepare('SELECT id FROM users WHERE id = ?')
      .get(user.id) as unknown as { id: string } | undefined;
    if (existing) {
      this.db
        .prepare('UPDATE users SET display_name = ? WHERE id = ?')
        .run(user.displayName, user.id);
    } else {
      this.db
        .prepare('INSERT INTO users (id, display_name) VALUES (?, ?)')
        .run(user.id, user.displayName);
    }
    return user;
  }
}

import { WebSocketServer, WebSocket } from 'ws';

/**
 * Internal ws endpoint on the API server that fans published events out to every connected live server instance.
 * @trace DSN-034 REQ-003 REQ-007 REQ-011
 */
export class EventFeed {
  private readonly server: WebSocketServer = new WebSocketServer({ noServer: true });
  private readonly clients: Set<WebSocket> = new Set();

  constructor() {
    this.server.on('connection', (socket: WebSocket) => {
      this.clients.add(socket);
      socket.on('close', () => this.clients.delete(socket));
      socket.on('error', () => this.clients.delete(socket));
    });
  }

  /** Sends the topic and payload to every connected instance; throws if the topic is empty. */
  publish(topic: string, payload: string): void {
    if (topic.trim() === '') {
      throw new Error('Topic must not be empty');
    }
    const message = JSON.stringify({ topic, payload });
    for (const socket of this.clients) {
      if (socket.readyState === WebSocket.OPEN) {
        socket.send(message);
      }
    }
  }
}

import { WebSocket } from 'ws';
import { LiveGateway } from './LiveGateway.js';

const RECONNECT_DELAY_MS = 1000;

/**
 * Client of the API server's internal ws event feed that forwards each incoming event to the live gateway.
 *
 * @trace DSN-032 REQ-003 REQ-007 REQ-011
 */
export class EventFeedClient {
  constructor(private readonly liveGateway: LiveGateway) {}

  /** Opens the ws connection to the API server feed and reconnects after it closes; throws nothing. */
  connect(): void {
    const base = (process.env.API_SERVER_URL ?? 'ws://localhost:8080').replace(/\/+$/, '');
    const socket = new WebSocket(`${base}/internal/live-update-server`);
    socket.on('message', (data) => {
      const event = JSON.parse(data.toString()) as { topic: string; payload: string };
      this.onEvent(event.topic, event.payload);
    });
    socket.on('close', () => {
      setTimeout(() => this.connect(), RECONNECT_DELAY_MS);
    });
    socket.on('error', () => {
      socket.close();
    });
  }

  /** Hands one feed event to the gateway for the item it concerns; throws if the topic is empty. */
  onEvent(topic: string, payload: string): void {
    if (topic.trim() === '') {
      throw new Error('Event topic is required');
    }
    this.liveGateway.broadcast(topic, payload);
  }
}

/**
 * WebSocket gateway for browsers that keeps watchers per item in memory and broadcasts only to them.
 * @trace DSN-033 REQ-003 REQ-009 REQ-011 REQ-004
 */
export class LiveGateway {
  private readonly watchers: Map<string, Set<string>> = new Map();
  private readonly outbox: Map<string, { itemId: string; message: string }[]> = new Map();

  constructor() {}

  /** Registers a client as watching an item; throws if an id is empty. */
  watch(clientId: string, itemId: string): void {
    this.requireId(clientId, 'Client id');
    this.requireId(itemId, 'Item id');
    let clients = this.watchers.get(itemId);
    if (!clients) {
      clients = new Set<string>();
      this.watchers.set(itemId, clients);
    }
    clients.add(clientId);
  }

  /** Removes a client's watch on an item; does nothing if it was not watching. */
  unwatch(clientId: string, itemId: string): void {
    this.requireId(clientId, 'Client id');
    this.requireId(itemId, 'Item id');
    const clients = this.watchers.get(itemId);
    if (!clients) {
      return;
    }
    clients.delete(clientId);
    if (clients.size === 0) {
      this.watchers.delete(itemId);
    }
  }

  /** Queues a message for every client watching the item only; throws if the item id is empty. */
  broadcast(itemId: string, message: string): void {
    this.requireId(itemId, 'Item id');
    const clients = this.watchers.get(itemId);
    if (!clients) {
      return;
    }
    for (const clientId of clients) {
      let queue = this.outbox.get(clientId);
      if (!queue) {
        queue = [];
        this.outbox.set(clientId, queue);
      }
      queue.push({ itemId, message });
    }
  }

  private requireId(value: string, label: string): void {
    if (typeof value !== 'string' || value.trim() === '') {
      throw new Error(`${label} must be a non-empty string`);
    }
  }
}

import { DatabaseSync } from 'node:sqlite';
import { Item } from './Item.js';
import { Bid } from './Bid.js';
import { Currency } from './Currency.js';
import { AuctionStatus } from './AuctionStatus.js';

type ItemRow = {
  id: string;
  seller_id: string;
  title: string;
  starting_price: number;
  currency: string;
  end_time: number;
  status: string;
  highest_bid_amount: number | null;
  highest_bidder_id: string | null;
  winner_id: string | null;
};

type BidRow = {
  id: string;
  item_id: string;
  bidder_id: string;
  amount: number;
  placed_at: number;
};

/**
 * Persists auction items and bids in the API server's SQLite database.
 * @trace DSN-029 REQ-001 REQ-002 REQ-004
 */
export class ItemStore {
  private readonly db: DatabaseSync;

  constructor(db: DatabaseSync) {
    this.db = db;
    this.db.exec(`CREATE TABLE IF NOT EXISTS items (
      id TEXT PRIMARY KEY,
      seller_id TEXT NOT NULL,
      title TEXT NOT NULL,
      starting_price REAL NOT NULL,
      currency TEXT NOT NULL,
      end_time INTEGER NOT NULL,
      status TEXT NOT NULL,
      highest_bid_amount REAL,
      highest_bidder_id TEXT,
      winner_id TEXT
    )`);
    this.db.exec(`CREATE TABLE IF NOT EXISTS bids (
      id TEXT PRIMARY KEY,
      item_id TEXT NOT NULL,
      bidder_id TEXT NOT NULL,
      amount REAL NOT NULL,
      placed_at INTEGER NOT NULL
    )`);
  }

  /** Inserts the item if its id is new, otherwise updates its stored row. */
  async saveItem(item: Item): Promise<Item> {
    const exists = this.db.prepare('SELECT id FROM items WHERE id = ?').get(item.id);
    const values = [
      item.sellerId,
      item.title,
      item.startingPrice,
      item.currency,
      item.endTime.getTime(),
      item.status,
      item.highestBidAmount,
      item.highestBidderId,
      item.winnerId,
    ];
    if (exists) {
      this.db
        .prepare(`UPDATE items SET seller_id = ?, title = ?, starting_price = ?, currency = ?,
          end_time = ?, status = ?, highest_bid_amount = ?, highest_bidder_id = ?, winner_id = ?
          WHERE id = ?`)
        .run(...values, item.id);
    } else {
      this.db
        .prepare(`INSERT INTO items (seller_id, title, starting_price, currency, end_time, status,
          highest_bid_amount, highest_bidder_id, winner_id, id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
        .run(...values, item.id);
    }
    return item;
  }

  /** Returns the stored item with the given id, or null when none is stored. */
  async findItem(id: string): Promise<Item | null> {
    const row = this.db
      .prepare('SELECT * FROM items WHERE id = ?')
      .get(id) as unknown as ItemRow | undefined;
    return row ? this.toItem(row) : null;
  }

  /** Returns all items whose status is open. */
  async findOpenItems(): Promise<Item[]> {
    const rows = this.db
      .prepare('SELECT * FROM items WHERE status = ? ORDER BY end_time')
      .all(AuctionStatus.open) as unknown as ItemRow[];
    return rows.map((row) => this.toItem(row));
  }

  /** Returns all open items whose end time is at or before the given instant. */
  async findDueItems(now: Date): Promise<Item[]> {
    const rows = this.db
      .prepare('SELECT * FROM items WHERE status = ? AND end_time <= ? ORDER BY end_time')
      .all(AuctionStatus.open, now.getTime()) as unknown as ItemRow[];
    return rows.map((row) => this.toItem(row));
  }

  /** Inserts the bid if its id is new, otherwise updates its stored row. */
  async saveBid(bid: Bid): Promise<Bid> {
    const exists = this.db.prepare('SELECT id FROM bids WHERE id = ?').get(bid.id);
    if (exists) {
      this.db
        .prepare('UPDATE bids SET item_id = ?, bidder_id = ?, amount = ?, placed_at = ? WHERE id = ?')
        .run(bid.itemId, bid.bidderId, bid.amount, bid.placedAt.getTime(), bid.id);
    } else {
      this.db
        .prepare('INSERT INTO bids (item_id, bidder_id, amount, placed_at, id) VALUES (?, ?, ?, ?, ?)')
        .run(bid.itemId, bid.bidderId, bid.amount, bid.placedAt.getTime(), bid.id);
    }
    return bid;
  }

  private toItem(row: ItemRow): Item {
    return new Item(
      row.id,
      row.seller_id,
      row.title,
      row.starting_price,
      row.currency as Currency,
      new Date(row.end_time),
      row.status as AuctionStatus,
      row.highest_bid_amount,
      row.highest_bidder_id,
      row.winner_id,
    );
  }
}

