  "path": "src/exchange-rates/ExchangeRateService.ts",
  "content": "import { Currency } from '../auction-api/Currency.js';
import { FrankfurterClient } from './FrankfurterClient.js';

interface CachedRates {
  rates: Record<string, number>;
  fetchedAt: number;
}

/**
 * Converts prices for display using rates cached for a configurable time; returns null when unavailable.
 * @trace DSN-025 REQ-005 REQ-010
 */
export class ExchangeRateService {
  private readonly cache = new Map<Currency, CachedRates>();

  constructor(private readonly frankfurterClient: FrankfurterClient, public cacheTtlMs: number) {}

  /** Converts an item-currency amount to the display currency; returns null when no rate is available, throws on invalid input. */
  async convert(amount: number, from: Currency, to: Currency): Promise<number | null> {
    if (!Number.isFinite(amount) || amount < 0) {
      throw new Error(`Invalid amount ${amount}`);
    }
    if (!Object.values(Currency).includes(from)) {
      throw new Error(`Unsupported currency ${from}`);
    }
    if (!Object.values(Currency).includes(to)) {
      throw new Error(`Unsupported currency ${to}`);
    }
    if (from === to) {
      return amount;
    }
    const rates = await this.getRates(from);
    if (rates === null) {
      return null;
    }
    const rate = rates[to];
    if (typeof rate !== 'number') {
      return null;
    }
    return amount * rate;
  }

  private async getRates(base: Currency): Promise<Record<string, number> | null> {
    const cached = this.cache.get(base);
    if (cached && Date.now() - cached.fetchedAt < this.cacheTtlMs) {
      return cached.rates;
    }
    try {
      const rates = await this.frankfurterClient.fetchRates(base);
      this.cache.set(base, { rates, fetchedAt: Date.now() });
      return rates;
    } catch {
      return null;
    }
  }
}
"
}

