import { createServer } from 'node:http';
import { randomUUID } from 'node:crypto';
import express from 'express';
import { WebSocketServer, WebSocket } from 'ws';
import { LiveGateway } from '../live-updates/LiveGateway.js';
import { EventFeedClient } from '../live-updates/EventFeedClient.js';

const liveGateway = new LiveGateway();
const eventFeedClient = new EventFeedClient(liveGateway);

// Sockets per watch key; the gateway decides who watches, this delivers to the sockets.
const sockets = new Map<string, WebSocket>();
const watchKeys = new Map<string, Set<string>>();
const keyOf = (itemId: string): string => `item:${itemId}`;

const gatewayBroadcast = liveGateway.broadcast.bind(liveGateway);
liveGateway.broadcast = (key: string, message: string): void => {
  gatewayBroadcast(key, message);
  for (const [clientId, keys] of watchKeys) {
    const socket = sockets.get(clientId);
    if (keys.has(key) && socket && socket.readyState === WebSocket.OPEN) {
      socket.send(JSON.stringify({ topic: key, payload: message }));
    }
  }
};

const app = express();
app.get('/health', (_req, res) => {
  res.json({ status: 'ok' });
});

const server = createServer(app);
const wss = new WebSocketServer({ server });
wss.on('connection', (socket) => {
  const clientId = randomUUID();
  sockets.set(clientId, socket);
  watchKeys.set(clientId, new Set());
  socket.on('message', (data) => {
    try {
      const msg = JSON.parse(data.toString()) as { action?: string; itemId?: string };
      const itemId = String(msg.itemId ?? '');
      if (msg.action === 'watch') {
        liveGateway.watch(clientId, keyOf(itemId));
        watchKeys.get(clientId)?.add(keyOf(itemId));
      } else if (msg.action === 'unwatch') {
        liveGateway.unwatch(clientId, keyOf(itemId));
        watchKeys.get(clientId)?.delete(keyOf(itemId));
      }
    } catch (err) {
      socket.send(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }));
    }
  });
  socket.on('close', () => {
    for (const key of watchKeys.get(clientId) ?? []) {
      liveGateway.unwatch(clientId, key);
    }
    watchKeys.delete(clientId);
    sockets.delete(clientId);
  });
});

eventFeedClient.connect();

const port = Number(process.env.LIVE_UPDATE_SERVER_PORT ?? 8081);
server.listen(port, () => console.log(`Live update server listening on ${port}`));

